// Package release verifies a software-update manifest (docs/design/254-p3-impl.md §3.7.1; 219-protocol.cddl
// update-manifest): the root key R (or the test root T in a bench build) endorses a signing key K in E, K signs the
// release object S, and the manifest repeats S's keys 1–4, 6. The format contract is the harness signer
// tests/tools/peer/signrel.py; testdata/ is generated by it.
package release

import (
	"bytes"
	"crypto/ecdh"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"

	"batman-prov/cbor"
	"batman-prov/cose"
)

// Reason codes (219-protocol.cddl reason-code) this package decides.
const (
	ReasonBoard        = 3  // payload for another board
	ReasonIntermediate = 4  // needs an intermediate version first (min_from)
	ReasonBootCfg      = 5  // needs a card reflash (boot config)
	ReasonDowngrade    = 6  // downgrade (or cross-channel) not allowed by S key 6
	ReasonBad          = 11 // content does not match its signature / version unparsable
	ReasonNoKey        = 24 // this image has no usable root key: no update through the app
)

// Content types and labels of the two signed objects (§3.7.1).
const (
	CTRelKey     = "batman/relkey"
	LabelRelKey  = "batman-relkey-v1"
	CTRelease    = "batman/release"
	LabelRelease = "batman-release-v1"
)

// Error is a refusal with its reason code; Why is for the log only.
type Error struct {
	Reason uint64
	Why    string
}

func (e *Error) Error() string           { return "release: " + e.Why }
func refuse(r uint64, why string) *Error { return &Error{Reason: r, Why: why} }

// ---- the image's trust (§3.7.1 key files) ------------------------------------------------------------------

// Trust is the image's root key as read from the read-only squashfs. State: "none" (no key file at all — an
// ordinary DEV image), "bad" (anything abnormal), or the first 8 bytes of the fingerprint in hex.
type Trust struct {
	Root      []byte // 65 B uncompressed P-256 point; nil unless State is a fingerprint
	MinSerial uint64
	State     string
}

// Fingerprint is the one definition shared by status, scripts/release-root.fpr and the app pin: sha256 of the 65 B point.
func Fingerprint(point []byte) []byte { h := sha256.Sum256(point); return h[:] }

// onCurve: a 65 B uncompressed point on P-256 (crypto/ecdh refuses anything else).
func onCurve(p []byte) bool { _, err := ecdh.P256().NewPublicKey(p); return err == nil }

const squashfsMagic = 0x73717368

// fsCheck lets tests run on a non-squashfs tmpdir; production requires squashfs.
var fsCheck = func(fd int) bool {
	var st syscall.Statfs_t
	return syscall.Fstatfs(fd, &st) == nil && uint64(st.Type) == squashfsMagic
}

var (
	reHexPoint = regexp.MustCompile(`^04[0-9a-f]{128}$`)
	reSerial   = regexp.MustCompile(`^[1-9][0-9]{0,9}$`)
)

// readKeyFile: "" + ok=false when absent; error when present but not a regular squashfs file of one line.
func readKeyFile(path string) (string, bool, error) {
	f, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_CLOEXEC, 0)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return "", false, nil
		}
		return "", true, err
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil || !fi.Mode().IsRegular() {
		return "", true, errors.New("not a regular file")
	}
	if !fsCheck(int(f.Fd())) {
		return "", true, errors.New("not on the read-only squashfs")
	}
	b, err := io.ReadAll(io.LimitReader(f, 257))
	if err != nil || len(b) > 256 {
		return "", true, errors.New("unreadable or too long")
	}
	s := string(b)
	s = strings.TrimSuffix(s, "\n") // one line: the content plus at most one trailing newline
	if strings.ContainsAny(s, "\n\r") {
		return "", true, errors.New("not one line")
	}
	return s, true, nil
}

// LoadTrust reads release-root.pub and release-min-serial from dir (production: /rom/usr/share/batman — the image's
// squashfs, never the overlay: a file placed at runtime must not make an image trust a key).
func LoadTrust(dir string) Trust {
	pubS, havePub, errP := readKeyFile(filepath.Join(dir, "release-root.pub"))
	serS, haveSer, errS := readKeyFile(filepath.Join(dir, "release-min-serial"))
	if !havePub && !haveSer {
		return Trust{State: "none"}
	}
	if errP != nil || errS != nil || !havePub || !haveSer || !reHexPoint.MatchString(pubS) || !reSerial.MatchString(serS) {
		return Trust{State: "bad"}
	}
	pt, _ := hex.DecodeString(pubS)
	if !onCurve(pt) {
		return Trust{State: "bad"}
	}
	ms, _ := strconv.ParseUint(serS, 10, 64)
	return Trust{Root: pt, MinSerial: ms, State: hex.EncodeToString(Fingerprint(pt)[:8])}
}

// ---- the manifest ----------------------------------------------------------------------------------------

// Release is a verified S (and its manifest).
type Release struct {
	Version       string
	Board         string
	Size          uint64 // the .tar.gz, bytes
	SumsSha       []byte // sha256(SHA256SUMS)
	DowngradeFrom []string
	MinFrom       string
	BootCfg       [][]byte // empty = no check
	BootTotal     uint64
	Serial        uint64
	ManifestSha   []byte // sha256 of the whole manifest bytes (the signature-check cache key, §3.7.4)
}

func getStr(m cbor.Map, k int) (string, bool) {
	v, ok := m.Get(k)
	s, ok2 := v.(string)
	return s, ok && ok2
}
func getU(m cbor.Map, k int) (uint64, bool) {
	v, ok := m.Get(k)
	u, ok2 := v.(uint64)
	return u, ok && ok2
}
func getB(m cbor.Map, k int, n int) ([]byte, bool) {
	v, ok := m.Get(k)
	b, ok2 := v.([]byte)
	return b, ok && ok2 && (n == 0 || len(b) == n)
}

func onlyKeys(m cbor.Map, keys ...uint64) bool {
	for _, e := range m {
		k, ok := e.K.(uint64)
		if !ok {
			return false
		}
		found := false
		for _, a := range keys {
			if a == k {
				found = true
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func strList(v any) ([]string, bool) {
	a, ok := v.([]any)
	if !ok {
		return nil, false
	}
	out := make([]string, 0, len(a))
	for _, x := range a {
		s, ok := x.(string)
		if !ok {
			return nil, false
		}
		out = append(out, s)
	}
	return out, true
}

func shaList(v any) ([][]byte, bool) {
	a, ok := v.([]any)
	if !ok {
		return nil, false
	}
	out := make([][]byte, 0, len(a))
	for _, x := range a {
		b, ok := x.([]byte)
		if !ok || len(b) != 32 {
			return nil, false
		}
		out = append(out, b)
	}
	return out, true
}

// Verify checks the manifest against the image's trust. Only the signature chain and the shapes; the node-side
// decisions (board, version rule, boot config) are Decide / the caller's.
func Verify(manifest []byte, t Trust) (*Release, *Error) {
	if t.Root == nil {
		return nil, refuse(ReasonNoKey, "this image trusts no release key ("+t.State+")")
	}
	item, err := cbor.Decode(manifest)
	if err != nil {
		return nil, refuse(ReasonBad, "manifest: not canonical CBOR")
	}
	m, ok := item.(cbor.Map)
	if !ok {
		return nil, refuse(ReasonBad, "manifest: not a map")
	}
	pairB, ok := getB(m, 5, 0)
	if !ok {
		return nil, refuse(ReasonBad, "manifest: no key 5")
	}
	pi, err := cbor.Decode(pairB)
	pair, ok := pi.([]any)
	if err != nil || !ok || len(pair) != 2 {
		return nil, refuse(ReasonBad, "manifest key 5: not [E, S]")
	}
	eRaw, ok1 := pair[0].([]byte)
	sRaw, ok2 := pair[1].([]byte)
	if !ok1 || !ok2 {
		return nil, refuse(ReasonBad, "manifest key 5: E / S not bstr")
	}
	eItem, err1 := cbor.Decode(eRaw)
	sItem, err2 := cbor.Decode(sRaw)
	if err1 != nil || err2 != nil {
		return nil, refuse(ReasonBad, "E / S: not canonical CBOR")
	}
	e, err := cose.VerifySign1(eItem, CTRelKey, LabelRelKey, [][]byte{t.Root})
	if err != nil {
		return nil, refuse(ReasonBad, "E: does not verify against the image's root key")
	}
	k, okK := getB(e.Payload, 1, 65)
	serial, okS := getU(e.Payload, 2)
	if !okK || !okS || serial < 1 || !onlyKeys(e.Payload, 1, 2) || !onCurve(k) {
		return nil, refuse(ReasonBad, "E: payload is not {1: K 65 B, 2: serial >= 1}")
	}
	if serial < t.MinSerial {
		return nil, refuse(ReasonBad, "E: serial "+strconv.FormatUint(serial, 10)+" is revoked (min "+strconv.FormatUint(t.MinSerial, 10)+")")
	}
	s, err := cose.VerifySign1(sItem, CTRelease, LabelRelease, [][]byte{k})
	if err != nil {
		return nil, refuse(ReasonBad, "S: does not verify against the endorsed key")
	}
	p := s.Payload
	if !onlyKeys(p, 1, 2, 3, 4, 6, 7, 8, 9) {
		return nil, refuse(ReasonBad, "S: unknown key")
	}
	r := &Release{Serial: serial}
	var ok3, ok4, ok5, ok6, ok9 bool
	r.Version, ok3 = getStr(p, 1)
	r.Board, ok4 = getStr(p, 2)
	r.Size, ok5 = getU(p, 3)
	r.SumsSha, ok6 = getB(p, 4, 32)
	r.BootTotal, ok9 = getU(p, 9)
	if !ok3 || !ok4 || !ok5 || !ok6 || !ok9 {
		return nil, refuse(ReasonBad, "S: keys 1-4 / 9 missing or of the wrong type")
	}
	if v, ok := p.Get(6); ok {
		if r.DowngradeFrom, ok = strList(v); !ok {
			return nil, refuse(ReasonBad, "S key 6: not [* tstr]")
		}
	}
	if v, ok := p.Get(7); ok {
		if r.MinFrom, ok = v.(string); !ok {
			return nil, refuse(ReasonBad, "S key 7: not tstr")
		}
	}
	if v, ok := p.Get(8); ok {
		if r.BootCfg, ok = shaList(v); !ok {
			return nil, refuse(ReasonBad, "S key 8: not [* sha256]")
		}
	}
	// the manifest repeats S's 1–4 and 6 (absent in both is equal)
	for _, key := range []int{1, 2, 3, 4, 6} {
		mv, mok := m.Get(key)
		sv, sok := p.Get(key)
		if mok != sok {
			return nil, refuse(ReasonBad, "manifest key "+strconv.Itoa(key)+" != S")
		}
		if mok {
			a, _ := cbor.Encode(mv)
			b, _ := cbor.Encode(sv)
			if !bytes.Equal(a, b) {
				return nil, refuse(ReasonBad, "manifest key "+strconv.Itoa(key)+" != S")
			}
		}
	}
	if _, ok := ParseVersion(r.Version); !ok {
		return nil, refuse(ReasonBad, "S: version unparsable ("+r.Version+")")
	}
	h := sha256.Sum256(manifest)
	r.ManifestSha = h[:]
	return r, nil
}

// ---- versions (§3.7.1 version rule) ------------------------------------------------------------------------

// Version is REL[-CH.N][+meta] with REL = X.Y.Z; meta is ignored.
type Version struct {
	X, Y, Z uint64
	Ch      string // "" = the shipped form without a suffix
	N       uint64
}

var reVersion = regexp.MustCompile(`^([0-9]+)\.([0-9]+)\.([0-9]+)(-(wsl|ci|rel)\.([0-9]+))?(\+[0-9A-Za-z.-]+)?$`)

// ParseVersion parses BATMAN_VERSION.
func ParseVersion(s string) (Version, bool) {
	g := reVersion.FindStringSubmatch(s)
	if g == nil {
		return Version{}, false
	}
	var v Version
	var err error
	nums := []*uint64{&v.X, &v.Y, &v.Z}
	for i, p := range nums {
		if *p, err = strconv.ParseUint(g[i+1], 10, 64); err != nil {
			return Version{}, false
		}
	}
	if g[4] != "" {
		v.Ch = g[5]
		if v.N, err = strconv.ParseUint(g[6], 10, 64); err != nil {
			return Version{}, false
		}
	}
	return v, true
}

// StripMeta drops "+meta" (the form S key 6 lists).
func StripMeta(s string) string {
	if i := strings.IndexByte(s, '+'); i >= 0 {
		return s[:i]
	}
	return s
}

// Compare: cmp < 0 a older than b, 0 equal, > 0 newer; ordered=false when the rule gives no order (same REL,
// different channels — N is counted per channel).
func Compare(a, b Version) (cmp int, ordered bool) {
	for _, d := range [][2]uint64{{a.X, b.X}, {a.Y, b.Y}, {a.Z, b.Z}} {
		if d[0] != d[1] {
			if d[0] < d[1] {
				return -1, true
			}
			return 1, true
		}
	}
	switch {
	case a.Ch == "" && b.Ch == "":
		return 0, true
	case a.Ch == "": // the shipped form > any -CH.N (D12)
		return 1, true
	case b.Ch == "":
		return -1, true
	case a.Ch != b.Ch:
		return 0, false
	case a.N < b.N:
		return -1, true
	case a.N > b.N:
		return 1, true
	}
	return 0, true
}

// Decide applies the version rule and key 7 to a verified release for a node running cur. 0 = allowed.
func Decide(cur string, r *Release) (uint64, string) {
	cv, ok := ParseVersion(cur)
	if !ok {
		return ReasonBad, "the running version " + cur + " is unparsable"
	}
	nv, _ := ParseVersion(r.Version)
	if r.MinFrom != "" {
		mv, ok := ParseVersion(r.MinFrom)
		if !ok {
			return ReasonBad, "S key 7 unparsable"
		}
		if c, ordered := Compare(cv, mv); !ordered || c < 0 {
			return ReasonIntermediate, "needs " + r.MinFrom + " first (running " + cur + ")"
		}
	}
	c, ordered := Compare(nv, cv)
	if ordered && c >= 0 { // newer, or the same = a reinstall
		return 0, ""
	}
	for _, d := range r.DowngradeFrom {
		if d == StripMeta(cur) {
			return 0, ""
		}
	}
	if !ordered {
		return ReasonDowngrade, "a different channel of the same release: S key 6 must list " + StripMeta(cur)
	}
	return ReasonDowngrade, "a downgrade from " + cur + ": S key 6 must list " + StripMeta(cur)
}
